"use client";

import { useState } from "react";
import type { Signal } from "@/lib/types";
import { submitFeedback } from "@/lib/api";

export interface AlertItem {
  id: string;
  ts: number;
  signal: Signal;
  message: string;
  severity: "warn" | "danger";
}

interface Props {
  alerts: AlertItem[];
}

const BORDER: Record<AlertItem["severity"], string> = {
  warn: "#f59e0b",
  danger: "#ef4444",
};

export function AlertsFeed({ alerts }: Props) {
  const [verdicts, setVerdicts] = useState<Record<string, "correct" | "incorrect">>({});

  const handleVerdict = async (a: AlertItem, verdict: "correct" | "incorrect") => {
    if (verdicts[a.id]) return;
    if (a.signal === "density") return;
    setVerdicts((v) => ({ ...v, [a.id]: verdict }));
    try {
      await submitFeedback(a.signal, verdict, a.id);
    } catch {
      setVerdicts((v) => {
        const next = { ...v };
        delete next[a.id];
        return next;
      });
    }
  };

  return (
    <div className="flex h-full flex-col rounded-lg bg-zinc-900/60 ring-1 ring-zinc-800">
      <div className="border-b border-zinc-800 px-4 py-2 text-xs uppercase tracking-wider text-zinc-500">
        Live alerts
      </div>
      <div className="flex-1 overflow-auto p-3">
        {alerts.length === 0 ? (
          <div className="py-6 text-center text-sm text-zinc-600">No alerts yet</div>
        ) : (
          <ul className="space-y-2">
            {alerts.slice(0, 60).map((a) => {
              const v = verdicts[a.id];
              const teachable = a.signal !== "density";
              return (
                <li
                  key={a.id}
                  className="rounded border-l-2 bg-zinc-950/60 px-3 py-2 text-sm"
                  style={{ borderColor: BORDER[a.severity] }}
                >
                  <div className="flex items-baseline justify-between gap-2">
                    <span className="text-xs text-zinc-500">{a.ts.toFixed(1)}s · {a.signal}</span>
                    {teachable && (
                      <span className="flex gap-1 text-xs">
                        <button
                          onClick={() => handleVerdict(a, "correct")}
                          disabled={!!v}
                          className={`rounded px-2 py-0.5 ${
                            v === "correct"
                              ? "bg-emerald-700 text-emerald-50"
                              : "bg-zinc-800 text-zinc-400 hover:bg-emerald-900 hover:text-emerald-200 disabled:opacity-40"
                          }`}
                        >
                          ✓ correct
                        </button>
                        <button
                          onClick={() => handleVerdict(a, "incorrect")}
                          disabled={!!v}
                          className={`rounded px-2 py-0.5 ${
                            v === "incorrect"
                              ? "bg-rose-700 text-rose-50"
                              : "bg-zinc-800 text-zinc-400 hover:bg-rose-900 hover:text-rose-200 disabled:opacity-40"
                          }`}
                        >
                          ✗ incorrect
                        </button>
                      </span>
                    )}
                  </div>
                  <div className="mt-0.5 text-zinc-200">{a.message}</div>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import type { Signal } from "@/lib/types";
import { submitFeedback } from "@/lib/api";

export interface AlertItem {
  id: string;
  ts: number;
  signal: Signal;
  message: string;
  severity: "warn" | "danger";
}

interface Props {
  alerts: AlertItem[];
  onJump?: (ts: number) => void;
}

const BORDER: Record<AlertItem["severity"], string> = {
  warn: "#f59e0b",
  danger: "#ef4444",
};

export function AlertsFeed({ alerts, onJump }: Props) {
  const [verdicts, setVerdicts] = useState<Record<string, "correct" | "incorrect">>({});

  const handleVerdict = async (e: React.MouseEvent, a: AlertItem, verdict: "correct" | "incorrect") => {
    e.stopPropagation(); // prevent jumping when clicking feedback
    if (verdicts[a.id]) return;
    if (a.signal === "density") return;
    setVerdicts((v) => ({ ...v, [a.id]: verdict }));
    try {
      await submitFeedback(a.signal, verdict, a.id);
    } catch {
      setVerdicts((v) => {
        const next = { ...v };
        delete next[a.id];
        return next;
      });
    }
  };

  return (
    <div className="flex h-full flex-col rounded-lg bg-zinc-900/60 ring-1 ring-zinc-800">
      <div className="border-b border-zinc-800 px-4 py-2 text-xs uppercase tracking-wider text-zinc-500">
        Live alerts
      </div>
      <div className="flex-1 overflow-auto p-3">
        {alerts.length === 0 ? (
          <div className="py-6 text-center text-sm text-zinc-600">No alerts yet</div>
        ) : (
          <ul className="space-y-2">
            {alerts.slice(0, 60).map((a) => {
              const v = verdicts[a.id];
              const teachable = a.signal !== "density";
              return (
                <li
                  key={a.id}
                  onClick={() => onJump && onJump(a.ts)}
                  className={`rounded border-l-2 bg-zinc-950/60 px-3 py-2 text-sm ${onJump ? "cursor-pointer hover:bg-zinc-900/80" : ""}`}
                  style={{ borderColor: BORDER[a.severity] }}
                >
                  <div className="flex items-baseline justify-between gap-2">
                    <span className="text-xs text-zinc-500">{a.ts.toFixed(1)}s · {a.signal}</span>
                    {teachable && (
                      <span className="flex gap-1 text-xs">
                        <button
                          onClick={(e) => handleVerdict(e, a, "correct")}
                          disabled={!!v}
                          className={`rounded px-2 py-0.5 ${
                            v === "correct"
                              ? "bg-emerald-700 text-emerald-50"
                              : "bg-zinc-800 text-zinc-400 hover:bg-emerald-900 hover:text-emerald-200 disabled:opacity-40"
                          }`}
                        >
                          ✓ correct
                        </button>
                        <button
                          onClick={(e) => handleVerdict(e, a, "incorrect")}
                          disabled={!!v}
                          className={`rounded px-2 py-0.5 ${
                            v === "incorrect"
                              ? "bg-rose-700 text-rose-50"
                              : "bg-zinc-800 text-zinc-400 hover:bg-rose-900 hover:text-rose-200 disabled:opacity-40"
                          }`}
                        >
                          ✗ incorrect
                        </button>
                      </span>
                    )}
                  </div>
                  <div className="mt-0.5 text-zinc-200">{a.message}</div>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { FrameEvent, MetaEvent, Signal, StreamEvent, VideoItem } from "@/lib/types";
import { analyzeWsUrl, videoFileUrl } from "@/lib/api";
import { DetectionOverlay } from "./DetectionOverlay";
import { RiskGauge } from "./RiskGauge";
import { StatPanel } from "./StatPanel";
import { AlertsFeed, type AlertItem } from "./AlertsFeed";
import { StopBanner } from "./StopBanner";

interface Props {
  video: VideoItem;
}

type ConnectionState = "idle" | "connecting" | "streaming" | "done" | "error";

const STOP_THRESHOLD = 95;
const STOP_COOLDOWN_MS = 30_000;
const ALT_WINDOW_MS = 5_000;
const ALT_AVG_THRESHOLD = 60;

export function Analyzer({ video }: Props) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const wsRef = useRef<WebSocket | null>(null);

  const [meta, setMeta] = useState<MetaEvent | null>(null);
  const [frames, setFrames] = useState<FrameEvent[]>([]);
  const [currentFrame, setCurrentFrame] = useState<FrameEvent | null>(null);
  const [alerts, setAlerts] = useState<AlertItem[]>([]);
  const [conn, setConn] = useState<ConnectionState>("idle");
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [size, setSize] = useState({ w: 0, h: 0 });

  const [stopActive, setStopActive] = useState(false);
  const [stopSignal, setStopSignal] = useState<Signal | null>(null);
  const stopCooldownUntil = useRef(0);

  const seenAlertIds = useRef<Set<string>>(new Set());

  useEffect(() => {
    setFrames([]);
    setCurrentFrame(null);
    setAlerts([]);
    setMeta(null);
    setErrorMsg(null);
    setStopActive(false);
    setStopSignal(null);
    seenAlertIds.current = new Set();
    stopCooldownUntil.current = 0;
    setConn("connecting");

    const ws = new WebSocket(analyzeWsUrl(video.id));
    wsRef.current = ws;

    ws.onmessage = (ev) => {
      const data = JSON.parse(ev.data) as StreamEvent;
      if (data.type === "meta") {
        setMeta(data);
        setConn("streaming");
      } else if (data.type === "frame") {
        setFrames((prev) => {
          const next = [...prev, data];
          if (next.length > 30000) next.shift();
          return next;
        });
        if (data.alerts.length > 0) {
          const fresh: AlertItem[] = [];
          for (const a of data.alerts) {
            if (seenAlertIds.current.has(a.id)) continue;
            seenAlertIds.current.add(a.id);
            fresh.push({
              id: a.id,
              ts: data.timestamp,
              signal: a.signal,
              message: a.message,
              severity: a.severity,
            });
          }
          if (fresh.length) setAlerts((prev) => [...fresh, ...prev].slice(0, 200));
        }
      } else if (data.type === "done") {
        setConn("done");
      } else if (data.type === "error") {
        setErrorMsg(data.message);
        setConn("error");
      }
    };

    ws.onerror = () => {
      setErrorMsg("WebSocket connection failed");
      setConn("error");
    };
    ws.onclose = () => {
      setConn((c) => (c === "streaming" ? "done" : c));
    };

    return () => {
      ws.close();
    };
  }, [video.id]);

  useEffect(() => {
    const el = videoRef.current;
    if (!el) return;
    let raf = 0;
    const tick = () => {
      const t = el.currentTime;
      const arr = frames;
      if (arr.length > 0) {
        let lo = 0, hi = arr.length - 1, best = 0;
        while (lo <= hi) {
          const mid = (lo + hi) >> 1;
          if (arr[mid].timestamp <= t) {
            best = mid;
            lo = mid + 1;
          } else {
            hi = mid - 1;
          }
        }
        setCurrentFrame(arr[best]);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [frames]);

  useEffect(() => {
    if (!currentFrame) return;
    if (stopActive) return;
    if (Date.now() < stopCooldownUntil.current) return;
    if (currentFrame.risk_score >= STOP_THRESHOLD) {
      setStopSignal(currentFrame.dominant_signal);
      setStopActive(true);
    }
  }, [currentFrame, stopActive]);

  const handleStopDismiss = useCallback(() => {
    setStopActive(false);
    setStopSignal(null);
    stopCooldownUntil.current = Date.now() + STOP_COOLDOWN_MS;
  }, []);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const ro = new ResizeObserver(() => {
      setSize({ w: el.clientWidth, h: el.clientHeight });
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const fileUrl = useMemo(() => videoFileUrl(video.id), [video.id]);

  const recommendAlternative = useMemo(() => {
    if (!currentFrame || frames.length < 4) return false;
    const tEnd = currentFrame.timestamp;
    const tStart = tEnd - ALT_WINDOW_MS / 1000;
    let sum = 0;
    let n = 0;
    for (let i = frames.length - 1; i >= 0; i--) {
      const f = frames[i];
      if (f.timestamp > tEnd) continue;
      if (f.timestamp < tStart) break;
      sum += f.risk_score;
      n++;
    }
    return n > 0 && sum / n >= ALT_AVG_THRESHOLD;
  }, [currentFrame, frames]);

  const status = useMemo(() => {
    if (conn === "connecting") return { label: "Connecting…", color: "#a1a1aa" };
    if (conn === "streaming") return { label: `Analyzing · ${frames.length} frames`, color: "#60a5fa" };
    if (conn === "done") return { label: `Done · ${frames.length} frames`, color: "#10b981" };
    if (conn === "error") return { label: "Error", color: "#ef4444" };
    return { label: "Idle", color: "#71717a" };
  }, [conn, frames.length]);

  const handleExport = () => {
    const payload = {
      video: { id: video.id, name: video.name },
      meta,
      exported_at: new Date().toISOString(),
      frames,
      alerts,
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `metro-escalator-${video.name.replace(/\.[^.]+$/, "")}-${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="grid h-full gap-4 lg:grid-cols-[3fr_1.4fr]">
      <div className="flex flex-col gap-3">
        <div ref={containerRef} className="relative aspect-video w-full overflow-hidden rounded-xl bg-black ring-1 ring-zinc-800">
          <video
            ref={videoRef}
            src={fileUrl}
            controls
            playsInline
            className="absolute inset-0 h-full w-full"
            onLoadedMetadata={(e) => {
              const v = e.currentTarget;
              setSize({ w: v.clientWidth, h: v.clientHeight });
            }}
          />
          <DetectionOverlay
            frame={currentFrame}
            videoWidth={meta?.width ?? 0}
            videoHeight={meta?.height ?? 0}
            displayWidth={size.w}
            displayHeight={size.h}
            laneSeparators={meta?.lane_separators ?? null}
          />
          <StopBanner active={stopActive} signal={stopSignal} onDismiss={handleStopDismiss} />
        </div>

        <div className="flex items-center justify-between rounded-lg bg-zinc-900/60 px-4 py-2 ring-1 ring-zinc-800">
          <div className="flex items-center gap-3">
            <span className="h-2 w-2 rounded-full" style={{ background: status.color }} />
            <span className="text-sm" style={{ color: status.color }}>{status.label}</span>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-xs text-zinc-500">
              {meta ? `${meta.width}×${meta.height} · ${meta.fps.toFixed(1)} fps · stride ${meta.stride} · ${meta.lanes} lanes` : "—"}
            </span>
            <button
              onClick={handleExport}
              disabled={frames.length === 0}
              className="rounded bg-zinc-800 px-3 py-1 text-xs font-medium text-zinc-200 hover:bg-zinc-700 disabled:opacity-40"
            >
              Extract data
            </button>
          </div>
        </div>

        {errorMsg && (
          <div className="rounded-lg border border-red-900 bg-red-950/40 px-4 py-2 text-sm text-red-300">
            {errorMsg}
          </div>
        )}
      </div>

      <div className="flex flex-col gap-4">
        <div className="rounded-xl bg-zinc-900/60 p-4 ring-1 ring-zinc-800">
          <RiskGauge score={currentFrame?.risk_score ?? 0} label="Risk score" />
        </div>
        <StatPanel frame={currentFrame} recommendAlternative={recommendAlternative} />
        <div className="min-h-[18rem] flex-1">
          <AlertsFeed alerts={alerts} />
        </div>
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { FrameEvent, MetaEvent, Signal, StreamEvent, VideoItem } from "@/lib/types";
import { analyzeWsUrl, videoFileUrl, submitFeedback } from "@/lib/api";
import { DetectionOverlay } from "./DetectionOverlay";
import { RiskGauge } from "./RiskGauge";
import { StatPanel } from "./StatPanel";
import { AlertsFeed, type AlertItem } from "./AlertsFeed";
import { StopBanner } from "./StopBanner";
import type { PersonRisk } from "@/lib/types";

interface Props {
  video: VideoItem;
}

type ConnectionState = "idle" | "connecting" | "streaming" | "done" | "error";

const STOP_THRESHOLD = 95;
const STOP_COOLDOWN_MS = 30_000;
const ALT_WINDOW_MS = 5_000;
const ALT_AVG_THRESHOLD = 60;

export function Analyzer({ video }: Props) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const wsRef = useRef<WebSocket | null>(null);

  const [meta, setMeta] = useState<MetaEvent | null>(null);
  const [frames, setFrames] = useState<FrameEvent[]>([]);
  const [currentFrame, setCurrentFrame] = useState<FrameEvent | null>(null);
  const [alerts, setAlerts] = useState<AlertItem[]>([]);
  const [conn, setConn] = useState<ConnectionState>("idle");
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [size, setSize] = useState({ w: 0, h: 0 });

  const [stopActive, setStopActive] = useState(false);
  const [stopSignal, setStopSignal] = useState<Signal | null>(null);
  const stopCooldownUntil = useRef(0);

  const seenAlertIds = useRef<Set<string>>(new Set());

  const [feedbackPopup, setFeedbackPopup] = useState<{person: PersonRisk, x: number, y: number} | null>(null);
  const handlePersonClick = useCallback((person: PersonRisk, x: number, y: number) => {
    if (videoRef.current) {
      videoRef.current.pause();
    }
    setFeedbackPopup({ person, x, y });
  }, []);

  const submitManualFeedback = async (signal: Signal) => {
    if (!feedbackPopup) return;
    try {
      await submitFeedback(signal, "correct"); // false negative: make model more sensitive
    } catch (e) {
      console.error(e);
    }
    setFeedbackPopup(null);
  };

  useEffect(() => {
    setFrames([]);
    setCurrentFrame(null);
    setAlerts([]);
    setMeta(null);
    setErrorMsg(null);
    setStopActive(false);
    setStopSignal(null);
    seenAlertIds.current = new Set();
    stopCooldownUntil.current = 0;
    setConn("connecting");

    const ws = new WebSocket(analyzeWsUrl(video.id));
    wsRef.current = ws;

    ws.onmessage = (ev) => {
      const data = JSON.parse(ev.data) as StreamEvent;
      if (data.type === "meta") {
        setMeta(data);
        setConn("streaming");
      } else if (data.type === "frame") {
        setFrames((prev) => {
          const next = [...prev, data];
          if (next.length > 30000) next.shift();
          return next;
        });
        if (data.alerts.length > 0) {
          const fresh: AlertItem[] = [];
          for (const a of data.alerts) {
            if (seenAlertIds.current.has(a.id)) continue;
            seenAlertIds.current.add(a.id);
            fresh.push({
              id: a.id,
              ts: data.timestamp,
              signal: a.signal,
              message: a.message,
              severity: a.severity,
            });
          }
          if (fresh.length) setAlerts((prev) => [...fresh, ...prev].slice(0, 200));
        }
      } else if (data.type === "done") {
        setConn("done");
      } else if (data.type === "error") {
        setErrorMsg(data.message);
        setConn("error");
      }
    };

    ws.onerror = () => {
      setErrorMsg("WebSocket connection failed");
      setConn("error");
    };
    ws.onclose = () => {
      setConn((c) => (c === "streaming" ? "done" : c));
    };

    return () => {
      ws.close();
    };
  }, [video.id]);

  useEffect(() => {
    const el = videoRef.current;
    if (!el) return;
    let raf = 0;
    const tick = () => {
      const t = el.currentTime;
      const arr = frames;
      if (arr.length > 0) {
        let lo = 0, hi = arr.length - 1, best = 0;
        while (lo <= hi) {
          const mid = (lo + hi) >> 1;
          if (arr[mid].timestamp <= t) {
            best = mid;
            lo = mid + 1;
          } else {
            hi = mid - 1;
          }
        }
        setCurrentFrame(arr[best]);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [frames]);

  useEffect(() => {
    if (!currentFrame) return;
    if (stopActive) return;
    if (Date.now() < stopCooldownUntil.current) return;
    if (currentFrame.risk_score >= STOP_THRESHOLD) {
      setStopSignal(currentFrame.dominant_signal);
      setStopActive(true);
    }
  }, [currentFrame, stopActive]);

  const handleStopDismiss = useCallback(() => {
    setStopActive(false);
    setStopSignal(null);
    stopCooldownUntil.current = Date.now() + STOP_COOLDOWN_MS;
  }, []);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const ro = new ResizeObserver(() => {
      setSize({ w: el.clientWidth, h: el.clientHeight });
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const fileUrl = useMemo(() => videoFileUrl(video.id), [video.id]);

  const recommendAlternative = useMemo(() => {
    if (!currentFrame || frames.length < 4) return false;
    const tEnd = currentFrame.timestamp;
    const tStart = tEnd - ALT_WINDOW_MS / 1000;
    let sum = 0;
    let n = 0;
    for (let i = frames.length - 1; i >= 0; i--) {
      const f = frames[i];
      if (f.timestamp > tEnd) continue;
      if (f.timestamp < tStart) break;
      sum += f.risk_score;
      n++;
    }
    return n > 0 && sum / n >= ALT_AVG_THRESHOLD;
  }, [currentFrame, frames]);

  const status = useMemo(() => {
    if (conn === "connecting") return { label: "Connecting…", color: "#a1a1aa" };
    if (conn === "streaming") return { label: `Analyzing · ${frames.length} frames`, color: "#60a5fa" };
    if (conn === "done") return { label: `Done · ${frames.length} frames`, color: "#10b981" };
    if (conn === "error") return { label: "Error", color: "#ef4444" };
    return { label: "Idle", color: "#71717a" };
  }, [conn, frames.length]);

  const handleExport = () => {
    const payload = {
      video: { id: video.id, name: video.name },
      meta,
      exported_at: new Date().toISOString(),
      frames,
      alerts,
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `metro-escalator-${video.name.replace(/\.[^.]+$/, "")}-${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="grid h-full gap-4 lg:grid-cols-[3fr_1.4fr]">
      {feedbackPopup && (
        <div 
          className="fixed z-50 flex flex-col gap-2 rounded-lg bg-zinc-900 p-3 shadow-xl ring-1 ring-zinc-700"
          style={{ 
            top: Math.max(0, Math.min(feedbackPopup.y + 15, typeof window !== "undefined" ? window.innerHeight - 200 : 0)), 
            left: Math.max(0, Math.min(feedbackPopup.x + 15, typeof window !== "undefined" ? window.innerWidth - 220 : 0))
          }}
        >
          <div className="flex justify-between items-center mb-1 border-b border-zinc-700 pb-1">
            <span className="text-xs font-semibold text-zinc-300">Missed issue for #{feedbackPopup.person.track_id}?</span>
            <button onClick={() => setFeedbackPopup(null)} className="text-zinc-500 hover:text-zinc-300">×</button>
          </div>
          <div className="text-xs text-zinc-400 mb-1">Select the main problem:</div>
          <div className="grid grid-cols-2 gap-2">
            {(["fall", "sitting", "counterflow", "facing_back", "running", "stuff"] as Signal[]).map(sig => (
              <button 
                key={sig} 
                onClick={() => submitManualFeedback(sig)}
                className="rounded bg-zinc-800 px-2 py-1.5 text-xs text-zinc-300 hover:bg-emerald-900 hover:text-emerald-100 transition-colors text-left"
              >
                {sig}
              </button>
            ))}
          </div>
        </div>
      )}

      <div className="flex flex-col gap-3">
        <div ref={containerRef} className="relative aspect-video w-full overflow-hidden rounded-xl bg-black ring-1 ring-zinc-800">
          <video
            ref={videoRef}
            src={fileUrl}
            controls
            playsInline
            className="absolute inset-0 h-full w-full"
            onLoadedMetadata={(e) => {
              const v = e.currentTarget;
              setSize({ w: v.clientWidth, h: v.clientHeight });
            }}
          />
          <DetectionOverlay
            frame={currentFrame}
            videoWidth={meta?.width ?? 0}
            videoHeight={meta?.height ?? 0}
            displayWidth={size.w}
            displayHeight={size.h}
            laneSeparators={meta?.lane_separators ?? null}
            onPersonClick={handlePersonClick}
          />
          <StopBanner active={stopActive} signal={stopSignal} onDismiss={handleStopDismiss} />
        </div>

        <div className="flex items-center justify-between rounded-lg bg-zinc-900/60 px-4 py-2 ring-1 ring-zinc-800">
          <div className="flex items-center gap-3">
            <span className="h-2 w-2 rounded-full" style={{ background: status.color }} />
            <span className="text-sm" style={{ color: status.color }}>{status.label}</span>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-xs text-zinc-500">
              {meta ? `${meta.width}×${meta.height} · ${meta.fps.toFixed(1)} fps · stride ${meta.stride} · ${meta.lanes} lanes` : "—"}
            </span>
            <button
              onClick={handleExport}
              disabled={frames.length === 0}
              className="rounded bg-zinc-800 px-3 py-1 text-xs font-medium text-zinc-200 hover:bg-zinc-700 disabled:opacity-40"
            >
              Extract data
            </button>
          </div>
        </div>

        {errorMsg && (
          <div className="rounded-lg border border-red-900 bg-red-950/40 px-4 py-2 text-sm text-red-300">
            {errorMsg}
          </div>
        )}
      </div>

      <div className="flex flex-col gap-4">
        <div className="rounded-xl bg-zinc-900/60 p-4 ring-1 ring-zinc-800">
          <RiskGauge score={currentFrame?.risk_score ?? 0} label="Risk score" />
        </div>
        <StatPanel frame={currentFrame} recommendAlternative={recommendAlternative} />
        <div className="min-h-[18rem] flex-1">
          <AlertsFeed
            alerts={alerts}
            onJump={(ts) => {
              if (videoRef.current) videoRef.current.currentTime = ts;
            }}
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { FrameEvent, LaneSeparator } from "@/lib/types";
import { riskColor } from "./RiskGauge";

interface Props {
  frame: FrameEvent | null;
  videoWidth: number;
  videoHeight: number;
  displayWidth: number;
  displayHeight: number;
  laneSeparators: LaneSeparator[] | null;
}

export function DetectionOverlay({ frame, videoWidth, videoHeight, displayWidth, displayHeight, laneSeparators }: Props) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    canvas.width = displayWidth;
    canvas.height = displayHeight;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!frame || videoWidth === 0 || videoHeight === 0) return;

    const sx = displayWidth / videoWidth;
    const sy = displayHeight / videoHeight;

    const seps = laneSeparators ?? [];
    const lanes = seps.length + 1;
    ctx.save();
    ctx.lineWidth = 2;
    ctx.strokeStyle = "rgba(56, 189, 248, 0.9)";
    ctx.shadowColor = "rgba(0, 0, 0, 0.7)";
    ctx.shadowBlur = 4;
    for (const [[tx, ty], [bx, by]] of seps) {
      ctx.beginPath();
      ctx.moveTo(tx * displayWidth, ty * displayHeight);
      ctx.lineTo(bx * displayWidth, by * displayHeight);
      ctx.stroke();
    }
    ctx.shadowBlur = 0;

    const bottomYs: number[] = [0, ...seps.map((s) => s[1][0]), 1];
    ctx.font = "bold 12px ui-sans-serif, system-ui";
    ctx.textBaseline = "middle";
    for (let i = 0; i < lanes; i++) {
      const cxNorm = (bottomYs[i] + bottomYs[i + 1]) / 2;
      const cx = cxNorm * displayWidth;
      const cy = displayHeight - 18;
      const dir = frame.lane_directions?.[i] ?? "unknown";
      const text = `Lane ${i + 1} · ${dir}`;
      const tw = ctx.measureText(text).width;
      ctx.fillStyle = "rgba(2, 6, 23, 0.75)";
      ctx.fillRect(cx - tw / 2 - 6, cy - 10, tw + 12, 20);
      ctx.fillStyle = "rgba(56, 189, 248, 1)";
      ctx.fillText(text, cx - tw / 2, cy);
    }
    ctx.textBaseline = "alphabetic";
    ctx.restore();

    ctx.font = "12px ui-sans-serif, system-ui";
    ctx.lineWidth = 2;

    for (const obj of frame.objects ?? []) {
      const [x1, y1, x2, y2] = obj.bbox;
      const x = x1 * sx;
      const y = y1 * sy;
      const w = (x2 - x1) * sx;
      const h = (y2 - y1) * sy;
      ctx.strokeStyle = obj.stationary ? "#a855f7" : "#a8a29e";
      ctx.setLineDash(obj.stationary ? [] : [3, 3]);
      ctx.strokeRect(x, y, w, h);
      ctx.setLineDash([]);
      const label = obj.stationary ? `${obj.cls} (left)` : obj.cls;
      ctx.fillStyle = obj.stationary ? "#a855f7" : "#a8a29e";
      const tw = ctx.measureText(label).width + 8;
      ctx.fillRect(x, y - 16, tw, 16);
      ctx.fillStyle = "#0a0a0f";
      ctx.fillText(label, x + 4, y - 4);
    }

    for (const p of frame.persons) {
      const [x1, y1, x2, y2] = p.bbox;
      const x = x1 * sx;
      const y = y1 * sy;
      const w = (x2 - x1) * sx;
      const h = (y2 - y1) * sy;

      const color = riskColor(p.risk * 100);
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = p.flags.length ? 2.5 : 1;
      ctx.strokeRect(x, y, w, h);

      if (p.head_bbox) {
        const [hx1, hy1, hx2, hy2] = p.head_bbox;
        ctx.lineWidth = 2;
        ctx.strokeRect(hx1 * sx, hy1 * sy, (hx2 - hx1) * sx, (hy2 - hy1) * sy);
      }

      const label = `#${p.track_id}·L${p.lane + 1}${p.flags.length ? " " + p.flags.join(",") : ""}`;
      ctx.lineWidth = 2;
      const tw = ctx.measureText(label).width + 8;
      ctx.fillRect(x, y - 16, tw, 16);
      ctx.fillStyle = "#0a0a0f";
      ctx.fillText(label, x + 4, y - 4);
    }
  }, [frame, videoWidth, videoHeight, displayWidth, displayHeight]);

  return <canvas ref={canvasRef} className="pointer-events-none absolute inset-0 h-full w-full" />;
}

"use client";

import { useEffect, useRef } from "react";
import type { FrameEvent, LaneSeparator } from "@/lib/types";
import { riskColor } from "./RiskGauge";

interface Props {
  frame: FrameEvent | null;
  videoWidth: number;
  videoHeight: number;
  displayWidth: number;
  displayHeight: number;
  laneSeparators: LaneSeparator[] | null;
  onPersonClick?: (person: import("@/lib/types").PersonRisk, x: number, y: number) => void;
}

export function DetectionOverlay({ frame, videoWidth, videoHeight, displayWidth, displayHeight, laneSeparators, onPersonClick }: Props) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    canvas.width = displayWidth;
    canvas.height = displayHeight;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!frame || videoWidth === 0 || videoHeight === 0) return;

    const sx = displayWidth / videoWidth;
    const sy = displayHeight / videoHeight;

    const seps = laneSeparators ?? [];
    const lanes = seps.length + 1;
    ctx.save();
    ctx.lineWidth = 2;
    ctx.strokeStyle = "rgba(56, 189, 248, 0.9)";
    ctx.shadowColor = "rgba(0, 0, 0, 0.7)";
    ctx.shadowBlur = 4;
    for (const [[tx, ty], [bx, by]] of seps) {
      ctx.beginPath();
      ctx.moveTo(tx * displayWidth, ty * displayHeight);
      ctx.lineTo(bx * displayWidth, by * displayHeight);
      ctx.stroke();
    }
    ctx.shadowBlur = 0;

    const bottomYs: number[] = [0, ...seps.map((s) => s[1][0]), 1];
    ctx.font = "bold 12px ui-sans-serif, system-ui";
    ctx.textBaseline = "middle";
    for (let i = 0; i < lanes; i++) {
      const cxNorm = (bottomYs[i] + bottomYs[i + 1]) / 2;
      const cx = cxNorm * displayWidth;
      const cy = displayHeight - 18;
      const dir = frame.lane_directions?.[i] ?? "unknown";
      const text = `Lane ${i + 1} · ${dir}`;
      const tw = ctx.measureText(text).width;
      ctx.fillStyle = "rgba(2, 6, 23, 0.75)";
      ctx.fillRect(cx - tw / 2 - 6, cy - 10, tw + 12, 20);
      ctx.fillStyle = "rgba(56, 189, 248, 1)";
      ctx.fillText(text, cx - tw / 2, cy);
    }
    ctx.textBaseline = "alphabetic";
    ctx.restore();

    ctx.font = "12px ui-sans-serif, system-ui";
    ctx.lineWidth = 2;

    for (const obj of frame.objects ?? []) {
      const [x1, y1, x2, y2] = obj.bbox;
      const x = x1 * sx;
      const y = y1 * sy;
      const w = (x2 - x1) * sx;
      const h = (y2 - y1) * sy;
      ctx.strokeStyle = obj.stationary ? "#a855f7" : "#a8a29e";
      ctx.setLineDash(obj.stationary ? [] : [3, 3]);
      ctx.strokeRect(x, y, w, h);
      ctx.setLineDash([]);
      const label = obj.stationary ? `${obj.cls} (left)` : obj.cls;
      ctx.fillStyle = obj.stationary ? "#a855f7" : "#a8a29e";
      const tw = ctx.measureText(label).width + 8;
      ctx.fillRect(x, y - 16, tw, 16);
      ctx.fillStyle = "#0a0a0f";
      ctx.fillText(label, x + 4, y - 4);
    }

    for (const p of frame.persons) {
      const [x1, y1, x2, y2] = p.bbox;
      const x = x1 * sx;
      const y = y1 * sy;
      const w = (x2 - x1) * sx;
      const h = (y2 - y1) * sy;

      const color = riskColor(p.risk * 100);
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = p.flags.length ? 2.5 : 1;
      ctx.strokeRect(x, y, w, h);

      if (p.head_bbox) {
        const [hx1, hy1, hx2, hy2] = p.head_bbox;
        ctx.lineWidth = 2;
        ctx.strokeRect(hx1 * sx, hy1 * sy, (hx2 - hx1) * sx, (hy2 - hy1) * sy);
      }

      const label = `#${p.track_id}·L${p.lane + 1}${p.flags.length ? " " + p.flags.join(",") : ""}`;
      ctx.lineWidth = 2;
      const tw = ctx.measureText(label).width + 8;
      ctx.fillRect(x, y - 16, tw, 16);
      ctx.fillStyle = "#0a0a0f";
      ctx.fillText(label, x + 4, y - 4);
    }
  }, [frame, videoWidth, videoHeight, displayWidth, displayHeight, laneSeparators]);

  const sx = videoWidth > 0 ? displayWidth / videoWidth : 1;
  const sy = videoHeight > 0 ? displayHeight / videoHeight : 1;

  return (
    <>
      <canvas ref={canvasRef} className="pointer-events-none absolute inset-0 h-full w-full" />
      {frame && onPersonClick && videoWidth > 0 && videoHeight > 0 && frame.persons.map((p) => (
        <div
          key={p.track_id}
          className="absolute cursor-pointer"
          title={`Report missed issue for #${p.track_id}`}
          style={{
            left: p.bbox[0] * sx,
            top: p.bbox[1] * sy,
            width: (p.bbox[2] - p.bbox[0]) * sx,
            height: (p.bbox[3] - p.bbox[1]) * sy,
          }}
          onClick={(e) => {
            e.stopPropagation();
            onPersonClick(p, e.clientX, e.clientY);
          }}
        />
      ))}
    </>
  );
}
